/**
 * 阳子博客主脚本
 * - Service Worker支持
 * - 性能监控
 * - 动态资源加载
 * - 页面交互（文章列表与搜索由首页维护）
 */

(function() {
    'use strict';

    // Resolve from this script, so article subdirectories and project pages
    // register the same worker without taking over other sites on the domain.
    const BLOG_BASE_URL = new URL('.', document.currentScript && document.currentScript.src
        ? document.currentScript.src : document.baseURI);

    // ============================================
    // Service Worker 管理
    // ============================================
    class ServiceWorkerManager {
        constructor() {
            this.worker = null;
            this.isSupported = 'serviceWorker' in navigator;
            this.cacheStats = {
                hits: 0,
                misses: 0,
                total: 0
            };
        }

        async init() {
            if (!this.isSupported) {
                console.warn('Service Worker not supported');
                return false;
            }

            try {
                this.worker = await navigator.serviceWorker.register(new URL('sw.js', BLOG_BASE_URL).href, {
                    scope: BLOG_BASE_URL.href,
                    updateViaCache: 'none'
                });

                // 监听Worker消息
                navigator.serviceWorker.addEventListener('message', (event) => {
                    this.handleWorkerMessage(event.data);
                });

                console.log('Service Worker initialized: true');
                return true;
            } catch (error) {
                console.error('Service Worker registration failed:', error);
                return false;
            }
        }

        async prewarmCache() {
            return this.sendMessage('precache');
        }

        async getCacheStats() {
            const stats = await this.sendMessage('get-stats');
            if (stats) this.cacheStats = stats;
            return stats;
        }

        async clearCache() {
            const result = await this.sendMessage('clear-cache');
            if (result && result.success) {
                this.cacheStats = { hits: 0, misses: 0, total: 0 };
            }
            return result;
        }

        async sendMessage(type) {
            if (!this.worker) return null;
            const target = this.worker.active || this.worker.waiting || this.worker.installing;
            if (!target) return null;
            return new Promise((resolve) => {
                const channel = new MessageChannel();
                let finished = false;
                const finish = (result) => {
                    if (finished) return;
                    finished = true;
                    clearTimeout(timeout);
                    channel.port1.close();
                    channel.port2.close();
                    resolve(result);
                };
                const timeout = setTimeout(() => finish(null), 10000);
                channel.port1.onmessage = (event) => finish(event.data);
                channel.port1.onmessageerror = () => finish(null);
                try {
                    target.postMessage({ type }, [channel.port2]);
                } catch (_) {
                    finish(null);
                }
            });
        }

        handleWorkerMessage(data) {
            if (data && data.type === 'performance') {
                const stats = data.data || data;
                this.cacheStats = {
                    hits: stats.hits,
                    misses: stats.misses,
                    total: stats.hits + stats.misses,
                    hitRate: stats.hitRate
                };
            }
        }

        getStats() {
            return this.cacheStats;
        }
    }

    // ============================================
    // 性能监控
    // ============================================
    class PerformanceMonitor {
        constructor() {
            this.metrics = [];
            this.enabled = true;
            this.startTime = performance.now();
            this.observers = [];
        }

        startTiming(label) {
            if (!this.enabled) return null;
            return performance.mark(label);
        }

        endTiming(label) {
            if (!this.enabled) return null;
            performance.mark(label);
            performance.measure(label, label);
            
            const measure = performance.getEntriesByName(label)[0];
            if (measure) {
                this.metrics.push({
                    name: label,
                    duration: measure.duration,
                    startTime: measure.startTime
                });
                
                // 清理旧的度量
                if (this.metrics.length > 100) {
                    this.metrics.shift();
                }
                
                return measure.duration;
            }
            
            performance.clearMarks();
            performance.clearMeasures(label);
            return null;
        }

        markFCP() {
            if (!this.enabled) return;
            performance.mark('FCP');
        }

        markLCP() {
            if (!this.enabled) return;
            performance.mark('LCP');
        }

        markCLS() {
            if (!this.enabled) return;
            performance.mark('CLS');
        }

        measureFCP() {
            if (!this.enabled) return null;
            performance.measure('FCP', 'FCP');
            const entries = performance.getEntriesByName('FCP');
            performance.clearMarks();
            
            if (entries && entries.length > 0) {
                const measure = entries[0];
                this.metrics.push({
                    name: 'FCP',
                    duration: measure.duration
                });
                return measure.duration;
            }
            return null;
        }

        measureLCP() {
            if (!this.enabled) return null;
            performance.measure('LCP', 'FCP');
            const entries = performance.getEntriesByName('LCP');
            performance.clearMarks();
            
            if (entries && entries.length > 0) {
                const measure = entries[0];
                this.metrics.push({
                    name: 'LCP',
                    duration: measure.duration
                });
                return measure.duration;
            }
            return null;
        }

        measureCLS() {
            if (!this.enabled) return null;
            performance.measure('CLS', 'CLS');
            const entries = performance.getEntriesByName('CLS');
            performance.clearMarks();
            
            if (entries && entries.length > 0) {
                const measure = entries[0];
                this.metrics.push({
                    name: 'CLS',
                    duration: measure.duration
                });
                return measure.duration;
            }
            return null;
        }

        observeWebVitals() {
            if (!this.enabled || !('PerformanceObserver' in window)) return;

            const vitalsObserver = new PerformanceObserver((list) => {
                const entry = list.getEntries()[0];
                
                if (entry) {
                    this.metrics.push({
                        name: entry.name,
                        value: entry.value,
                        delta: entry.delta
                    });

                    // 清理旧的指标
                    if (this.metrics.length > 50) {
                        this.metrics.shift();
                    }

                    console.log(`Web Vital: ${entry.name}`, entry.value, entry.delta);
                }
            });

            // 监控关键指标
            vitalsObserver.observe({ entryTypes: ['paint', 'largest-contentful-paint', 'layout-shift', 'cumulative-layout-shift', 'total-blocking-time', 'first-input-delay'] });
            
            this.observers.push(vitalsObserver);
        }

        getMetrics() {
            // 计算页面总时间
            const pageLoadTime = performance.now() - this.startTime;
            
            return {
                pageLoadTime,
                vitals: this.metrics.filter(m => m.value !== undefined),
                custom: this.metrics.filter(m => m.duration !== undefined)
            };
        }

        report() {
            if (!this.enabled) return;

            const metrics = this.getMetrics();
            
            console.group('📊 Performance Report');
            console.log(`Page Load Time: ${metrics.pageLoadTime.toFixed(0)}ms`);
            
            // Web Vitals
            console.group('Web Vitals');
            metrics.vitals.forEach(metric => {
                if (metric.value !== undefined) {
                    const value = metric.value.toFixed(2);
                    const delta = metric.delta !== undefined ? `(${metric.delta > 0 ? '+' : ''}${metric.delta.toFixed(2)})` : '';
                    console.log(`  ${metric.name}: ${value}ms ${delta}`);
                }
            });
            console.groupEnd();
            
            // 自定义指标
            console.group('Custom Metrics');
            metrics.custom.forEach(metric => {
                if (metric.duration !== undefined) {
                    console.log(`  ${metric.name}: ${metric.duration.toFixed(2)}ms`);
                }
            });
            console.groupEnd();
            
            console.groupEnd();

            // 检查Service Worker状态
            if (window.swManager && window.swManager.getStats) {
                const swStats = window.swManager.getStats();
                console.group('Service Worker Cache');
                console.log(`  Hits: ${swStats.hits}`);
                console.log(`  Misses: ${swStats.misses}`);
                console.log(`  Total: ${swStats.total}`);
                console.log(`  Hit Rate: ${swStats.hitRate}%`);
                console.groupEnd();
            }
        }
    }

    // ============================================
    // 核心功能
    // ============================================

    // 导航链接平滑滚动
    function setupSmoothScroll() {
        const navLinks = document.querySelectorAll('nav a[href^="#"]');
        navLinks.forEach(link => {
            link.addEventListener('click', function(e) {
                e.preventDefault();
                const targetId = this.getAttribute('href');
                const targetElement = document.querySelector(targetId);
                if (targetElement) {
                    targetElement.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            });
        });
    }

    // 滚动元素观察
    function setupScrollAnimations() {
        const animatedElements = document.querySelectorAll('.blog-post, .trait, .friend-link');
        
        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.style.opacity = '1';
                    entry.target.style.transform = 'translateY(0)';
                }
            });
        }, { threshold: 0.1, rootMargin: '0px 0px -50px 0px' });

        animatedElements.forEach(el => {
            el.style.opacity = '0';
            el.style.transform = 'translateY(20px)';
            el.style.transition = 'opacity 0.6s ease, transform 0.6s ease';
            observer.observe(el);
        });
    }

    // 菜单切换
    function setupMobileMenu() {
        const menuToggle = document.getElementById('menu-toggle');
        const nav = document.querySelector('nav');
        
        if (menuToggle && nav) {
            menuToggle.addEventListener('click', function() {
                nav.classList.toggle('active');
                menuToggle.classList.toggle('active');
            });
        }
    }

    // 日期相对时间显示
    function setupRelativeDates() {
        const dateElements = document.querySelectorAll('.post-date');
        
        dateElements.forEach(element => {
            const dateString = element.textContent;
            const date = new Date(dateString);
            
            if (!isNaN(date.getTime())) {
                const relativeTime = getRelativeTime(date);
                element.setAttribute('title', dateString);
                element.textContent = relativeTime;
            }
        });

        function getRelativeTime(date) {
            const now = new Date();
            const diff = now.getTime() - date.getTime();
            const seconds = Math.floor(diff / 1000);
            const minutes = Math.floor(seconds / 60);
            const hours = Math.floor(minutes / 60);
            const days = Math.floor(hours / 24);

            if (days > 365) {
                return Math.floor(days / 365) + '年前';
            } else if (days > 30) {
                return Math.floor(days / 30) + '个月前';
            } else if (days > 0) {
                return days + '天前';
            } else if (hours > 0) {
                return hours + '小时前';
            } else if (minutes > 0) {
                return minutes + '分钟前';
            } else {
                return '刚刚';
            }
        }
    }

    // 阅读进度条
    function setupReadingProgress() {
        const progressBar = document.getElementById('reading-progress');
        
        window.addEventListener('scroll', function() {
            const winScroll = document.body.scrollTop || document.documentElement.scrollTop;
            const height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
            const scrolled = (winScroll / height) * 100;
            
            if (progressBar) {
                progressBar.style.width = scrolled + '%';
            }
        });
    }

    // Service Worker状态检查
    function checkServiceWorker() {
        const swStatus = document.getElementById('sw-status');
        const cacheStatus = document.getElementById('cache-status');
        if (!swStatus && !cacheStatus) return;
        if ('serviceWorker' in navigator) {
            navigator.serviceWorker.getRegistration(BLOG_BASE_URL.href).then((registration) => {
                if (registration && registration.scope === BLOG_BASE_URL.href) {
                    if (swStatus) {
                        swStatus.textContent = registration.active ? '✅ Active' : '⏳️ Installing';
                        swStatus.style.color = registration.active ? '#00ff88' : '#ffaa00';
                    }
                    
                    // 检查缓存状态
                    if (cacheStatus && window.swManager && window.swManager.getCacheStats) {
                        window.swManager.getCacheStats().then(stats => {
                            if (stats) {
                                cacheStatus.textContent = `✅ ${stats.hits} hits / ${stats.total} requests`;
                                cacheStatus.style.color = '#00ff88';
                            } else {
                                cacheStatus.textContent = '⏳️ Initializing...';
                                cacheStatus.style.color = '#ffaa00';
                            }
                        });
                    }
                } else {
                    if (swStatus) {
                        swStatus.textContent = '⏳️ Not registered';
                        swStatus.style.color = '#ffaa00';
                    }
                    if (cacheStatus) cacheStatus.textContent = 'N/A';
                }
            }).catch(() => {
                if (swStatus) swStatus.textContent = 'Unavailable';
                if (cacheStatus) cacheStatus.textContent = 'N/A';
            });
        } else {
            if (swStatus) {
                swStatus.textContent = 'Not supported';
                swStatus.style.color = '#ff4444';
            }
            if (cacheStatus) cacheStatus.textContent = 'N/A';
        }
    }

    // 性能控制台（开发模式）
    function setupDebugControls() {
        if (!location.search.includes('debug=true')) {
            document.addEventListener('keydown', (e) => {
                if (e.ctrlKey && e.key === 'p') {
                    e.preventDefault();
                    window.yokoBlog.reportPerformance();
                }
                if (e.ctrlKey && e.key === 'c') {
                    e.preventDefault();
                    window.yokoBlog.clearCache();
                    console.log('Cache cleared!');
                }
                if (e.ctrlKey && e.key === 's') {
                    e.preventDefault();
                    console.log('Cache stats:', window.yokoBlog.getCacheStats());
                }
            });

            // 添加性能信息到页面
            const perfInfo = document.createElement('div');
            perfInfo.id = 'performance-info';
            perfInfo.style.cssText = `
                position: fixed;
                bottom: 20px;
                right: 20px;
                background: rgba(0, 0, 0, 0.8);
                color: #00ff00;
                padding: 15px;
                border-radius: 10px;
                font-family: 'Fira Code', monospace;
                font-size: 12px;
                z-index: 9999;
                opacity: 0.9;
            `;
            // perfInfo.innerHTML = `
            //     <div style="margin-bottom: 10px;">Debug: Ctrl+P (Perf), Ctrl+C (Clear), Ctrl+S (Stats)</div>
            //     <div id="perf-stats"></div>
            // `;
            document.body.appendChild(perfInfo);

            // 每5秒更新一次统计
            setInterval(() => {
                const stats = window.yokoBlog.getCacheStats();
                if (stats) {
                    const perfStats = document.getElementById('perf-stats');
                    if (perfStats) {
                        perfStats.innerHTML = `
                            Hits: ${stats.hits} | Misses: ${stats.misses} | Total: ${stats.total} | Hit Rate: ${stats.hitRate}%
                        `;
                    }
                }
            }, 5000);
        }
    }

    // ============================================
    // 初始化全局实例
    // ============================================
    window.swManager = new ServiceWorkerManager();
    window.perfMonitor = new PerformanceMonitor();

    // 阳子博客全局API
    window.yokoBlog = {
        sw: window.swManager,
        perf: window.perfMonitor,
        
        // 快捷方法
        reportPerformance: () => window.perfMonitor.report(),
        clearCache: () => window.swManager.clearCache(),
        getCacheStats: () => window.swManager.getCacheStats(),
        
        // 性能监控
        startTiming: (label) => window.perfMonitor.startTiming(label),
        endTiming: (label) => window.perfMonitor.endTiming(label),
        measureFCP: () => window.perfMonitor.measureFCP(),
        measureLCP: () => window.perfMonitor.measureLCP(),
        measureCLS: () => window.perfMonitor.measureCLS(),
        measureTTFB: () => window.perfMonitor.measureTTFB(),
        measureINP: () => window.perfMonitor.measureINP(),
        
        getMetrics: () => window.perfMonitor.getMetrics()
    };

    // ============================================
    // DOM加载完成后执行
    // ============================================
    document.addEventListener('DOMContentLoaded', () => {
        console.log('🚀 阳子博客初始化开始...');
        
        // 首页保留生成器输出的最新文章；搜索只由 index.html 绑定。

        // 导航平滑滚动
        setupSmoothScroll();
        
        // 滚动动画
        setupScrollAnimations();
        
        // 移动菜单
        setupMobileMenu();
        
        // 日期相对时间
        setupRelativeDates();
        
        // 阅读进度条
        setupReadingProgress();
        
        // 性能控制台
        setupDebugControls();
        
        // Service Worker状态
        window.swManager.init().then(checkServiceWorker);
        
        // 页面加载完成后报告
        window.addEventListener('load', () => {
            setTimeout(() => {
                window.perfMonitor.report();
            }, 1000);
        });
        
        // 页面卸载前报告
        window.addEventListener('beforeunload', () => {
            window.perfMonitor.report();
        });

        console.log('✅ 阳子博客初始化完成！');
    });

})();
